"""PreToolUse guard for Claude Code: blocks edits of generated files and bypassing git hooks, and
asks before tests that reach the real shops.

Reads the hook payload (JSON) from stdin. Exit code 2 blocks the tool call and shows the message on
stderr to Claude; printing a JSON "ask" decision makes Claude Code prompt the user; anything else
lets the call through. A guardrail for the agent, not a security boundary: the prek hook
`local-only-paths` is the net for `.notes/` and `data/` when commands are typed by hand.
"""

import json
import re
import shlex
import sys

GENERATED = {
    "frontend/src/routeTree.gen.ts": "it is generated by the TanStack Router plugin (vite)",
    "frontend/src/api/schema.d.ts": "it is generated from the API: run `just gen-api`",
}
GIT_OPTIONS_WITH_VALUE = {"-C", "-c", "--git-dir", "--work-tree", "--namespace", "--exec-path"}
SHORT_FLAGS = re.compile(r"^-[A-Za-z]+$")
LIVE_MARKER = re.compile(r"(?<!not )\blive\b")
HOOK_SKIPPING_ENV = ("SKIP=", "PREK_SKIP=", "PRE_COMMIT_ALLOW_NO_CONFIG=")

Verdict = tuple[str, str] | None
"""("deny" | "ask", reason), or None to allow."""


def check_edit(path: str) -> Verdict:
    for generated, why in GENERATED.items():
        if path == generated or path.endswith("/" + generated):
            return "deny", f"Do not edit {generated} by hand: {why}."
    return None


def words_of(command: str) -> list[str]:
    # punctuation_chars splits `;`, `&&` and `|` off words (`core.hooksPath;` -> two tokens).
    lexer = shlex.shlex(command, posix=True, punctuation_chars=True)
    lexer.whitespace_split = True
    try:
        return list(lexer)
    except ValueError:
        return command.split()


def split_git(words: list[str]) -> tuple[list[str], str, list[str]]:
    """(values of `-c`, subcommand, its arguments), skipping git's global options."""
    configs: list[str] = []
    i = 0
    while i < len(words) and words[i].startswith("-"):
        if words[i] == "-c" and i + 1 < len(words):
            configs.append(words[i + 1])
        i += 2 if words[i] in GIT_OPTIONS_WITH_VALUE else 1
    if i >= len(words):
        return configs, "", []
    return configs, words[i], words[i + 1 :]


def has_short_flag(args: list[str], flag: str) -> bool:
    """`-n`, and `n` inside a cluster such as `-anm`."""
    return any(SHORT_FLAGS.match(arg) and flag in arg[1:] for arg in args)


def check_git(words: list[str]) -> Verdict:
    configs, sub, args = split_git(words)
    if any(c.lower().startswith("core.hookspath") for c in configs):
        return "deny", "Do not override core.hooksPath: prek installs the hooks into .git/hooks."
    no_verify = any(a.startswith("--no-v") for a in args)  # git accepts unique prefixes
    if sub in ("commit", "push", "merge") and (
        no_verify or (sub == "commit" and has_short_flag(args, "n"))
    ):
        return "deny", "Do not bypass the git hooks (--no-verify): fix what they report instead."
    if sub == "add" and ("--force" in args or has_short_flag(args, "f")):
        return "deny", (
            "Do not force-add files: ignored paths stay out of the repository "
            "(.notes/ and data/ must never be committed)."
        )
    if sub == "config" and any(a.lower().startswith("core.hookspath") for a in args):
        return "deny", "Do not change core.hooksPath: prek installs the hooks into .git/hooks."
    return None


def runs_live_tests(words: list[str]) -> bool:
    if "pytest" not in words:
        return False
    markers = [words[i + 1] for i, w in enumerate(words[:-1]) if w == "-m"]
    markers += [w.removeprefix("-m") for w in words if w.startswith("-m") and len(w) > 2]
    return any(LIVE_MARKER.search(m) for m in markers) or any("tests/live" in w for w in words)


def check_bash(command: str) -> Verdict:
    words = words_of(command)
    if any(w.startswith(HOOK_SKIPPING_ENV) for w in words) and "git" in words:
        return "deny", "Do not skip git hooks through the environment: fix what they report."
    for i, word in enumerate(words):
        if word == "git":
            verdict = check_git(words[i + 1 :])
            if verdict:
                return verdict
    if runs_live_tests(words):
        return "ask", "Live tests send requests to the real shops."
    return None


def main() -> int:
    payload = json.load(sys.stdin)
    tool, data = payload.get("tool_name", ""), payload.get("tool_input", {})
    if tool == "Bash":
        verdict = check_bash(data.get("command", ""))
    else:
        verdict = check_edit(data.get("file_path", "") or data.get("notebook_path", ""))
    if verdict is None:
        return 0
    kind, reason = verdict
    if kind == "ask":
        decision = {"hookEventName": "PreToolUse", "permissionDecision": "ask"}
        print(json.dumps({"hookSpecificOutput": decision | {"permissionDecisionReason": reason}}))
        return 0
    print(reason, file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main())
